package edu.casestudy.merkle.service; import edu.casestudy.merkle.data.*;import edu.casestudy.merkle.data.Entities.*;import edu.casestudy.merkle.data.Repositories.*;import edu.casestudy.merkle.core.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class CheckpointService {final IntegrityService integrity;final Checkpoints cps;final Records records;final String key;public CheckpointService(IntegrityService i,Checkpoints c,Records r,@Value("${app.checkpoint-key}")String k){integrity=i;cps=c;records=r;key=k;} public List<Checkpoint> list(UUID id){return cps.findByDatasetIdOrderByCreatedAtDesc(id);}@Transactional public Checkpoint create(UUID id){var d=integrity.dataset(id);var c=new Checkpoint();c.datasetId=id;c.datasetVersion=d.version;c.rootHash=integrity.tree(id).root();c.manifest=integrity.encode(integrity.manifest(integrity.tree(id),id));c.snapshot=records.findByDatasetIdOrderByPosition(id).stream().map(r->r.id+"\t"+r.position+"\t"+Base64.getEncoder().encodeToString(r.payload.getBytes(java.nio.charset.StandardCharsets.UTF_8))).collect(java.util.stream.Collectors.joining("\n"));c.signature=HashUtils.hex(HashUtils.hash(HashUtils.utf8(key+c.rootHash+c.manifest)));cps.save(c);integrity.audit(id,"CHECKPOINT_CREATED",c.rootHash);return c;}@Transactional public void restore(UUID id){var c=list(id).stream().findFirst().orElseThrow(()->new IllegalArgumentException("No trusted checkpoint to restore"));if(c.snapshot==null)throw new IllegalArgumentException("Checkpoint has no retained snapshot");records.deleteByDatasetId(id);for(String line:c.snapshot.split("\n")){if(line.isBlank())continue;var p=line.split("\t",3);var r=new DatasetRecord();r.id=UUID.fromString(p[0]);r.datasetId=id;r.position=Long.parseLong(p[1]);r.payload=new String(Base64.getDecoder().decode(p[2]),java.nio.charset.StandardCharsets.UTF_8);records.save(r);}integrity.bump(id);integrity.audit(id,"RECOVERY_RESTORED",c.id.toString());}}
